mapper.update:
update personal_settlement
set settlement_status = '지급완료', settled_at = now(), admin_id = #{adminId}
where settlement_id = #{settlementId}
and settlement_status = '정산대기'

mapper.select:
		select count(distinct pm.personal_match_id) 
		from personal_match pm join user u on (u.user_id=pm.user_id)
							   left join personal_match_participant pmp on (pmp.personal_match_id=pm.personal_match_id) and pmp.status = '결제완료'
            	    		   left join personal_settlement ps on (ps.personal_match_id=pm.personal_match_id)
		where pm.user_id=#{userId} and pm.status='경기 종료' and pm.match_date between #{startDate} and #{endDate}
			  and exists (select 1 from personal_match_participant p2
            			  where p2.personal_match_id = pm.personal_match_id and p2.status = '결제완료')		

  			  and pm.title like concat('%', #{keyword}, '%')


      		  and ps.settlement_status = #{settlementStatus}
